import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./AdminDashboard.css";

const AdminDashboard = () => {
  const navigate = (typeof useNavigate === "function" ? useNavigate() : () => {}) || (() => {});
  const [filter, setFilter] = useState("");

  const handleFilter = () => {
    // Put your real filter logic here (API call / state update)
    console.log("Filtering with:", filter);
  };

  const handleClear = () => {
    setFilter("");
    // Clear results or reset the view if needed
    console.log("Filter cleared");
  };

  return (
    <div className="admin-root">
      {/* DESKTOP: absolute header (floating pill across top) */}
      <header className="header-row-absolute">
        <div className="header-inner">
          <input
            className="filter-input-absolute"
            placeholder="Filter..."
            value={filter}
            onChange={(e) => setFilter(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") handleFilter();
              if (e.key === "Escape") handleClear();
            }}
          />

          <div className="header-actions">
            <button className="action" onClick={handleFilter} title="Apply filter">Filter</button>
            <button className="action" onClick={handleClear} title="Clear filter">Clear</button>
            <button className="action primary" onClick={() => navigate && navigate("/")}>Customer View</button>
          </div>
        </div>
      </header>

      {/* MOBILE: simple header in normal flow (shown only on small screens) */}
      <header className="header-row">
        <input
          className="filter-input-mobile"
          placeholder="Filter..."
          value={filter}
          onChange={(e) => setFilter(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter") handleFilter();
            if (e.key === "Escape") handleClear();
          }}
        />
      </header>

      {/* MAIN CONTENT */}
      <main className="main-area">
        <section className="page-shell">
          <h2 className="page-title">Analytics</h2>

          <div className="analytics-grid">
            <div className="analytics-card">
              <div className="card-value">12</div>
              <div className="card-label">Total Chef</div>
            </div>

            <div className="analytics-card">
              <div className="card-value">$1,245</div>
              <div className="card-label">Total Revenue</div>
            </div>

            <div className="analytics-card">
              <div className="card-value">85</div>
              <div className="card-label">Total Orders</div>
            </div>

            <div className="analytics-card">
              <div className="card-value">240</div>
              <div className="card-label">Total Clients</div>
            </div>
          </div>

          {/* Example content so you can see the spacing */}
          <div className="content-box">
            <p>
              This is the page shell content. On mobile the filter input (rounded pill) will sit above this
              white shell (like your Image 2). On desktop you'll see the floating absolute header pill across
              the top as before (Image 1).
            </p>
          </div>
        </section>
      </main>
    </div>
  );
};

export default AdminDashboard;
